#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const source = path.join(root, "agent", "alfi-structure");
const output = path.join(root, "src", "generated", "alfi-bundle.ts");

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walk(full) : [full];
  });
}

function relative(file) {
  return path.relative(source, file).replaceAll("\\", "/");
}

function normalizedBase64(file) {
  const content = fs.readFileSync(file, "utf8").replace(/\r\n?/g, "\n");
  return Buffer.from(content, "utf8").toString("base64");
}

const files = walk(source)
  .filter((file) => {
    const rel = relative(file);
    return rel === "SOUL.md" || rel.startsWith("config/") || rel.startsWith("skills/");
  })
  .sort((a, b) => relative(a).localeCompare(relative(b)))
  .map((file) => ({ path: relative(file), base64: normalizedBase64(file) }));

const cronManifestPath = path.join(source, "cron", "jobs.json");
const cronJobs = JSON.parse(fs.readFileSync(cronManifestPath, "utf8"));
if (!Array.isArray(cronJobs) || cronJobs.length === 0) {
  throw new Error("agent/alfi-structure/cron/jobs.json must contain at least one job");
}

const keys = new Set();
for (const job of cronJobs) {
  if (!job || typeof job !== "object") throw new Error("Every Alfi cron job must be an object");
  for (const field of ["key", "name", "schedule", "timezone", "deliver", "prompt"]) {
    if (typeof job[field] !== "string" || !job[field].trim()) {
      throw new Error(`Alfi cron job is missing ${field}`);
    }
  }
  if (!job.key.startsWith("alfi:")) throw new Error(`Cron key must start with alfi:: ${job.key}`);
  if (keys.has(job.key)) throw new Error(`Duplicate Alfi cron key: ${job.key}`);
  keys.add(job.key);
  if (!Array.isArray(job.skills) || job.skills.length === 0) {
    throw new Error(`Cron job ${job.key} must attach at least one skill`);
  }
  for (const skill of job.skills) {
    const skillPath = path.join(source, "skills", skill, "SKILL.md");
    if (typeof skill !== "string" || !fs.existsSync(skillPath)) {
      throw new Error(`Cron job ${job.key} references missing skill: ${skill}`);
    }
  }
}
cronJobs.sort((a, b) => a.key.localeCompare(b.key));

const skillNames = [
  ...new Set(
    files.flatMap((file) => {
      if (!file.path.endsWith("/SKILL.md")) return [];
      const content = Buffer.from(file.base64, "base64").toString("utf8");
      const match = content.match(/^name:\s*(.+)$/m);
      if (!match) throw new Error(`Alfi skill ${file.path} is missing a name`);
      return [match[1].trim()];
    }),
  ),
].sort((a, b) => a.localeCompare(b));

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(
  output,
  `// Generated by scripts/generate-alfi-bundle.mjs. Do not edit.\n` +
    `export interface AlfiDefaultCronJob {\n` +
    `  key: string;\n` +
    `  name: string;\n` +
    `  schedule: string;\n` +
    `  timezone: string;\n` +
    `  skills: readonly string[];\n` +
    `  deliver: string;\n` +
    `  prompt: string;\n` +
    `}\n\n` +
    `export const ALFI_BUNDLE = ${JSON.stringify(files, null, 2)} as const;\n\n` +
    `export const ALFI_SKILL_NAMES = ${JSON.stringify(skillNames)} as const;\n\n` +
    `export const ALFI_DEFAULT_CRON_JOBS = ${JSON.stringify(cronJobs, null, 2)} as const satisfies readonly AlfiDefaultCronJob[];\n`
);
console.log(`Generated ${files.length} Alfi files and ${cronJobs.length} cron defaults.`);
